const express = require('express');
require('reflect-metadata');
const { plainToInstance } = require('class-transformer');
const { validateOrReject, IsUUID, IsInt, IsOptional, IsString } = require('class-validator');
const { AppDataSource } = require('../dataSource');
const { PrescriptionRefill } = require('../entities/PrescriptionRefill');
const { Prescription } = require('../entities/Prescription');

const app = express();
app.use(express.json());

class RefillPrescriptionDto {
  @IsUUID()
  prescriptionId;

  @IsInt()
  pharmacyStoreId;

  @IsOptional()
  @IsString()
  specialInstructions;
}

const validateDto = (dtoClass) => async (req, res, next) => {
  try {
    const dtoInstance = plainToInstance(dtoClass, req.body);
    await validateOrReject(dtoInstance, { whitelist: true, forbidNonWhitelisted: true });
    req.dto = dtoInstance;
    next();
  } catch (errors) {
    res.status(400).json({ error: 'Validation failed', details: errors });
  }
};

app.post('/api/pharmacy/refills', validateDto(RefillPrescriptionDto), async (req, res) => {
  if (!req.user || !req.user.patientId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { prescriptionId, pharmacyStoreId, specialInstructions } = req.dto;
  const callerPatientId = req.user.patientId;

  // Verify prescription exists and belongs to the authenticated patient
  const rxRepo = AppDataSource.getRepository(Prescription);
  const prescription = await rxRepo.findOne({
    where: { id: prescriptionId, patientId: callerPatientId }
  });

  if (!prescription) {
    return res.status(404).json({ error: 'Prescription not found or unauthorized' });
  }

  const refillRepo = AppDataSource.getRepository(PrescriptionRefill);
  const newRefill = refillRepo.create({
    prescriptionId,
    patientId: callerPatientId,
    pharmacyStoreId,
    specialInstructions,
    status: 'SUBMITTED',
    createdAt: new Date()
  });

  await refillRepo.save(newRefill);
  res.status(201).json({ success: true, refillId: newRefill.id });
});

app.listen(7001);
